#define NUM_MEMORY_PORTS 2
#define NUM_MEMORY_SLOTS 1

#define GSOk 0
#define GSErrorUnformatted -1
#define GSErrorNoMedia -5
#define GSErrorNotEnoughSpace -7

class GenericGameSaver
{
public:
	static GenericGameSaver *inst() { return instance; }
	int getFirstCard() { return 0; }
	static int getInfo(int port, int slot, int *type, int *free, int *formatted);
	int getSavedGameSize() { return saved_game_size; }

private:
	static int saved_game_size;
	static GenericGameSaver *instance;
};

extern int notEnoughSpacePort, notEnoughSpaceSlot;

class MCDetectFrontEnd
{
public:
	int validCards();
};

__asm__(".equ _16GenericGameSaver$instance, 0x0041E5B8");
__asm__(".equ _16GenericGameSaver$saved_game_size, 0x0041E510");
__asm__(".equ getInfo__16GenericGameSaveriiPiN23, 0x001E3DC0");
__asm__(".equ notEnoughSpacePort, 0x003FCDF8");
__asm__(".equ notEnoughSpaceSlot, 0x003FCDFC");

int MCDetectFrontEnd::validCards()
{
	int port, slot, retVal, numCards = 0;
	int type, free, formatted;
	int numTooLittleSpace=0, numUnformatted=0;
	for(port = GenericGameSaver::inst()->getFirstCard(); port < NUM_MEMORY_PORTS; port++)
		for(slot = 0; slot < NUM_MEMORY_SLOTS; slot++)
		{
			retVal = GenericGameSaver::inst()->getInfo(port,slot, &type, &free, &formatted);
			if (retVal == GSOk && (unsigned int)free > (unsigned int)GenericGameSaver::inst()->getSavedGameSize())
			{
				numCards++;
			}
			else if (retVal == GSErrorUnformatted)
			{
				numUnformatted++;
			}
			else if (retVal == GSOk && (unsigned int)free <= (unsigned int)GenericGameSaver::inst()->getSavedGameSize())
			{
				numTooLittleSpace++;
				if (notEnoughSpacePort == -9999)
				{
					notEnoughSpacePort = port;
					notEnoughSpaceSlot = slot;
				}
			}
			// Otherwise we don't have a card
		}

	if (numCards)
	{
		return numCards;
	}
	else if (numUnformatted)
	{
		return 0;
	}
	else if (numTooLittleSpace)
	{
		return GSErrorNotEnoughSpace;
	}
	else
		return GSErrorNoMedia;

}
